#!/usr/bin/env node
/**
 * Generates docs/assets/js/data/search-index.js.
 *
 * The site has no server, so search cannot fetch an index at runtime. The
 * index is a plain script assigning window.HB.searchIndex, regenerated by
 * this tool and committed. The structure tests fail if it is stale.
 *
 * Entry fields (short names keep the file small):
 *   k  kind: "chapter" | "section" | "term" | "page"
 *   t  title shown in results
 *   s  subtitle (chapter for sections, definition for terms)
 *   u  relative URL
 *   w  extra keywords searched but not shown
 *   p  1 when the chapter is not written yet
 *
 * Usage: npm run build:search      (LOG_LEVEL=debug for detail)
 */
import { writeFileSync, existsSync } from "node:fs";
import { join } from "node:path";
import { pathToFileURL } from "node:url";
import { DATA_DIR, DOCS, loadData, readPage, headingsWithId, firstText } from "./lib/site.mjs";
import { logger } from "./lib/log.mjs";

const log = logger("search-index");
const OUT = join(DATA_DIR, "search-index.js");

function clip(text, max) {
  if (text.length <= max) return text;
  return text.slice(0, max - 1).replace(/\s+\S*$/, "") + "…";
}

/** Builds the index entries from nav, glossary and the written pages. */
export function buildIndex() {
  const { nav, glossary } = loadData();
  const entries = [];

  for (const ch of nav.chapters) {
    const label = `${ch.num} ${ch.title}`;
    if (ch.status !== "published") {
      entries.push({ k: "chapter", t: label, s: `Part ${ch.part} · not written yet`, u: nav.contentsHref(ch.num), w: ch.terms, p: 1 });
      continue;
    }
    if (!existsSync(join(DOCS, ch.file))) {
      log.warn(`chapter ${ch.num} is marked published but ${ch.file} is missing; skipped`);
      continue;
    }
    const html = readPage(ch.file);
    entries.push({ k: "chapter", t: label, s: clip(firstText(html, "p", "lead"), 140), u: ch.file, w: ch.terms });
    // Step headings (h3 with an id) are specific enough to be worth finding.
    // The eight beat headings are the same in every chapter, so they are left out.
    for (const hd of headingsWithId(html, 3)) {
      entries.push({ k: "section", t: hd.text, s: label, u: `${ch.file}#${hd.id}` });
    }
    log.debug(`indexed ${ch.file}`);
  }

  for (const ref of nav.reference || []) {
    entries.push({ k: "page", t: ref.title, s: ref.blurb, u: ref.file });
  }

  for (const [id, g] of Object.entries(glossary)) {
    entries.push({ k: "term", t: g.term, s: clip(g.def, 140), u: `glossary.html#${id}`, w: (g.aka || []).join(" ") });
  }
  return entries;
}

/** The exact file contents written to disk (also used by the tests). */
export function renderIndexFile(entries) {
  const lines = entries.map((e) => "  " + JSON.stringify(e));
  return [
    "/*",
    " * search-index.js: GENERATED by tools/build-search-index.mjs. Do not edit by hand.",
    " * Regenerate with: npm run build:search",
    " */",
    "window.HB = window.HB || {};",
    "window.HB.searchIndex = [",
    lines.join(",\n"),
    "];",
    "",
  ].join("\n");
}

if (import.meta.url === pathToFileURL(process.argv[1]).href) {
  const entries = buildIndex();
  writeFileSync(OUT, renderIndexFile(entries));
  const counts = entries.reduce((acc, e) => ((acc[e.k] = (acc[e.k] || 0) + 1), acc), {});
  log.info(`wrote ${entries.length} entries`, counts);
}
